<script>
document.addEventListener("DOMContentLoaded", () => {

  gsap.registerPlugin();

  const mm = gsap.matchMedia();

  mm.add("(min-width: 992px)", () => {

    const boxes = [
      {
        box: document.querySelector("[promise-box-active]"),
        image: document.querySelector("[promise-image-1]")
      },
      {
        box: document.querySelector("[promise-box-2]"),
        image: document.querySelector("[promise-image-2]")
      },
      {
        box: document.querySelector("[promise-box-3]"),
        image: document.querySelector("[promise-image-3]")
      },
      {
        box: document.querySelector("[promise-box-4]"),
        image: document.querySelector("[promise-image-4]")
      }
    ];

    function setActive(activeBox, activeImage) {

      boxes.forEach(item => {

        const box = item.box;

        // Box background
        gsap.to(box, {
          backgroundColor: "#FFFFFF",
          duration: 0.3,
          overwrite: true
        });

        // Text colors
        box.querySelectorAll(".fda-text-style-h6").forEach(text => {
          gsap.to(text, {
            color: "#332920",
            duration: 0.3,
            overwrite: true
          });
        });

        // Arrows
        const arrowOne = box.querySelector(".fda-promise-arrow-one");
        const arrowTwo = box.querySelector(".fda-promise-arrow-two");

        if (arrowOne) {
          gsap.to(arrowOne, {
            opacity: 1,
            duration: 0.3,
            overwrite: true
          });
        }

        if (arrowTwo) {
          gsap.to(arrowTwo, {
            opacity: 0,
            duration: 0.3,
            overwrite: true
          });
        }

        // Images
        if (item.image) {
          gsap.to(item.image, {
            opacity: 0,
            duration: 0.4,
            overwrite: true
          });
        }

      });

      // Active box
      gsap.to(activeBox, {
        backgroundColor: "#302627",
        duration: 0.3,
        overwrite: true
      });

      activeBox.querySelectorAll(".fda-text-style-h6").forEach(text => {
        gsap.to(text, {
          color: "#FFFFFF",
          duration: 0.3,
          overwrite: true
        });
      });

      const activeArrowOne = activeBox.querySelector(".fda-promise-arrow-one");
      const activeArrowTwo = activeBox.querySelector(".fda-promise-arrow-two");

      if (activeArrowOne) {
        gsap.to(activeArrowOne, {
          opacity: 0,
          duration: 0.3,
          overwrite: true
        });
      }

      if (activeArrowTwo) {
        gsap.to(activeArrowTwo, {
          opacity: 1,
          duration: 0.3,
          overwrite: true
        });
      }

      // Active image
      gsap.to(activeImage, {
        opacity: 1,
        duration: 0.4,
        overwrite: true
      });
    }

    // Initial State
    setActive(
      document.querySelector("[promise-box-active]"),
      document.querySelector("[promise-image-1]")
    );

    // Hover Events
    boxes.forEach(item => {
      item.box.addEventListener("mouseenter", () => {
        setActive(item.box, item.image);
      });
    });

  });

});
</script>


