<script src="https://cdn.jsdelivr.net/npm/gsap@3.12.5/dist/gsap.min.js"></script>
<script>
(function () {
  function initFdaMemorySliders() {
    var sliders = document.querySelectorAll('.fda-memorie-slider');

    sliders.forEach(function (slider) {
      // scale-in (slide becoming active) takes 2s, slow and deliberate.
      // scale-out (slide becoming inactive) stays tied to the slider's
      // own data-duration so it disappears in step with the slide change.
      var inDuration = 2;
      var outDuration = (parseInt(slider.getAttribute('data-duration'), 10) || 500) / 1000;

      var items = Array.prototype.slice.call(slider.querySelectorAll('.w-slide'))
        .map(function (slideEl) {
          var boxEl = slideEl.querySelector('[class*="fda-memory-center-box-"]');
          return boxEl ? { slideEl: slideEl, boxEl: boxEl, wasActive: false } : null;
        })
        .filter(Boolean);

      if (!items.length) return;

      function isActive(slideEl) {
        return slideEl.getAttribute('aria-hidden') !== 'true';
      }

      items.forEach(function (item) {
        item.wasActive = isActive(item.slideEl);
        gsap.set(item.boxEl, { scale: item.wasActive ? 1 : 0, transformOrigin: '50% 50%' });
      });

      function animate(boxEl, toActive) {
        gsap.to(boxEl, {
          scale: toActive ? 1 : 0,
          duration: toActive ? inDuration : outDuration,
          ease: toActive ? 'power2.out' : 'power2.in',
          overwrite: 'auto',
          onStart: function () { if (toActive) boxEl.style.pointerEvents = 'auto'; },
          onComplete: function () { if (!toActive) boxEl.style.pointerEvents = 'none'; }
        });
      }

      items.forEach(function (item) {
        var observer = new MutationObserver(function () {
          var nowActive = isActive(item.slideEl);
          if (nowActive !== item.wasActive) {
            item.wasActive = nowActive;
            animate(item.boxEl, nowActive);
          }
        });
        observer.observe(item.slideEl, { attributes: true, attributeFilter: ['aria-hidden'] });
      });
    });
  }

  if (window.Webflow && window.Webflow.push) {
    window.Webflow.push(initFdaMemorySliders);
  } else if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initFdaMemorySliders);
  } else {
    initFdaMemorySliders();
  }
})();
</script><script src="{{ asset('js/custom-animations.js') }}"></script>
